package com.bank.headcount;

import java.util.*;
import java.util.logging.*;

public class CountingDemo {
    private static final Logger log = Logger.getLogger("Headcount");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee("Rajesh", "IT"),
            new Employee("Amit", "IT"),
            new Employee("Priya", "Sales"),
            new Employee("Neha", "Sales"),
            new Employee("Vikram", "Risk"));
        HeadcountService service = new HeadcountService();

        Map<String, Long> counts = service.countByDepartment(staff);
        log.info(() -> "Head count per department: " + counts);
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final String name;
    private final String department;
    Employee(String name, String department) { this.name = name; this.department = department; }
    String getDepartment() { return department; }
}

// ─── Would be in service/HeadcountService.java ───
class HeadcountService {
    Map<String, Long> countByDepartment(List<Employee> staff) {
        return staff.stream()
            .collect(java.util.stream.Collectors.groupingBy(
                Employee::getDepartment,                 // classifier: department
                java.util.stream.Collectors.counting()));// downstream: count per group
    }
}
